package com.vandorlabs.neoforge.propulsion;
import com.vandorlabs.neoforge.client.NativePropulsionScreen;
import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
/** Actual native engine widgets, atlas, slider dragging, picker scrolling, resize and reload. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class PropulsionScreenChecks {
 private static final NativePropulsionBlock[] BLOCKS=new NativePropulsionBlock[3];private static BlockEntityType<NativePropulsionEntity> TYPE;private static final List<NativePropulsionSettingsEdit> EDITS=new ArrayList<>();private static NativePropulsionScreen screen;
 private static int ticks,stage,checks,frames;private static String capture;private static boolean captured;private static java.util.concurrent.CompletableFuture<Void> reload;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_PROPULSION_SCREEN_CHECK"));}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{String[] ids={"rocket_thruster","antigravity_plate","rocket_thruster_wedge"};for(int i=0;i<3;i++){BLOCKS[i]=new NativePropulsionBlock(ids[i],BlockBehaviour.Properties.of(),()->TYPE,id->null);h.register(ResourceLocation.parse("vandorlabs:propulsion_screen_fixture_"+i),BLOCKS[i]);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativePropulsionEntity>of((p,state)->new NativePropulsionEntity(TYPE,p,state),BLOCKS).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_screen_fixture"),TYPE);});}}
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Propulsion screen stage="+stage+": "+text);}
 private static void click(int id,int button){var widget=screen.button(id);need(widget!=null&&widget.active,"enabled button "+id);need(screen.mouseClicked(widget.getX()+widget.getWidth()/2D,widget.getY()+widget.getHeight()/2D,button),"actual click "+id);}
 private static void open(Minecraft mc,int family){var tile=new NativePropulsionEntity(TYPE,BlockPos.ZERO,BLOCKS[family].defaultBlockState());screen=new NativePropulsionScreen(new NativePropulsionMenu(null,37,tile),new Inventory(null),Component.literal(family==1?"Antigravity Plate":"Rocket Thruster"),EDITS::add);screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
 private static void widgets(Minecraft mc){open(mc,0);int sent=EDITS.size();need(screen.page()==0&&screen.button(2)!=null&&screen.button(3)!=null&&screen.button(4)!=null,"Source General engine controls");click(2,1);need(screen.choices().particleLevel()==3&&EDITS.size()==sent,"right-click previous particles stays draft");click(3,1);need(!screen.choices().join()&&EDITS.size()==sent,"join stays draft");screen.choose(64);need(screen.choices().sideTexture()==64&&EDITS.size()==sent,"ordinary material stays draft");click(101,0);need(screen.button(16).getMessage().getString().equals("Activation: Redstone ON"),"shared Source activation label");screen.channelField().setValue("31,");need(!screen.button(1).active&&EDITS.size()==sent,"malformed channel prevents submit");click(6,1);need(screen.choices().threshold()==7&&EDITS.size()==sent,"previous threshold and no premature send");click(5,1);click(16,1);need(screen.choices().analog()&&screen.choices().inverted(),"reverse boolean options");screen.channelField().setValue("31,32");need(screen.button(1).active&&EDITS.size()==sent,"valid channel remains draft");click(100,0);click(4,1);need(EDITS.size()==sent+1&&EDITS.getLast().choices().shape()==2&&EDITS.getLast().choices().channels().equals(ChannelList.of(31,32))&&screen.button(3)==null,"shape immediately submits complete draft and Wedge omits join");
 open(mc,0);sent=EDITS.size();click(4,0);need(EDITS.size()==sent+1,"shape-only send");click(1,0);need(EDITS.size()==sent+1,"Done after shape-only suppresses redundant submit");open(mc,1);need(screen.button(4)==null&&screen.button(3)!=null&&!screen.choices().updateShape(),"Hover no shape update");open(mc,2);need(screen.button(3)==null&&screen.button(4)!=null,"Wedge exposes shape without join");open(mc,0);var picker=screen.activePicker();picker.searchField().setValue("a");picker.searchField().setFocused(true);need(screen.keyPressed(69,0,0),"picker text owns inventory shortcut");int before=picker.scroll();need(screen.mouseScrolled(screen.panel().listX+5,picker.top()+5,0,-1)&&picker.scroll()>before,"picker wheel");int bottom=picker.top()+picker.visible()*22-1;need(screen.mouseClicked(screen.panel().listX+screen.panel().listWidth+2,bottom,0),"scrollbar press");int end=picker.scroll();need(screen.mouseDragged(screen.panel().listX+screen.panel().listWidth+2,picker.top(),0,0,-100)&&picker.scroll()<end,"scrollbar drag");screen.mouseReleased(0,0,0);click(101,0);click(100,0);need(screen.activePicker().searchField().getValue().equals("a"),"tabs preserve query");}
 private static void capture(String name){capture=name;captured=false;frames=0;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==9)return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<1800,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"title-only boundary");if(stage==0){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();stage=1;}else if(stage==1){widgets(mc);capture("propulsion-general.png");stage=2;}else if(stage==2&&captured){click(101,0);capture("propulsion-redstone.png");stage=3;}else if(stage==3&&captured){screen.init(mc,400,260);for(int id:new int[]{100,101,1,16,5,6}){var button=screen.button(id);need(button!=null&&button.getX()>=screen.panel().left&&button.getX()+button.getWidth()<=screen.panel().left+screen.panel().width&&button.getY()>=screen.panel().top&&button.getY()+button.getHeight()<=screen.panel().top+screen.panel().height,"small-screen bounds "+id);}reload=mc.reloadResourcePacks();stage=4;}else if(stage==4&&reload.isDone()){reload.join();screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());click(100,0);need(screen.activePicker().searchField().getValue().equals("a"),"reload retains query");capture("propulsion-reloaded.png");stage=5;}else if(stage==5&&captured){need(EDITS.stream().allMatch(edit->edit.window()==37&&edit.pos().equals(BlockPos.ZERO)),"all submissions retain menu identity");System.out.println("[vandorlabs][propulsion-screen] title PASS checks="+checks+" edits="+EDITS.size());stage=9;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var g=event.getGuiGraphics();g.flush();g.pose().pushPose();try{g.pose().translate(0,0,300);g.fill(0,0,Minecraft.getInstance().getWindow().getGuiScaledWidth(),Minecraft.getInstance().getWindow().getGuiScaledHeight(),0xFF101012);screen.render(g,0,0,0);g.flush();}finally{g.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||++frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->{captured=true;});}
}
